    /// RFC 3501 §7.1.1 untagged greeting.
    fn vector() -> Vec<u8> {
        vec![
            0x2a, 0x20, 0x4f, 0x4b, 0x20, 0x49, 0x4d, 0x41, 0x50, 0x34, 0x72, 0x65, 0x76, 0x31,
            0x0d, 0x0a,
        ]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Imap);
        assert!(p.find_layer(ProtoId::Imap).is_some());

        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Imap);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Imap);
        let l = p.find_layer(ProtoId::Imap).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Imap, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
